t.script:
document.addEventListener('DOMContentLoaded', function() {
    const dateInput = document.getElementById('b2b_requested_delivery_date');
    const shiftSelect = document.getElementById('b2b_delivery_shift');
    const notesInput = document.getElementById('b2b_delivery_notes');
    const statusEl = document.getElementById('b2b_schedule_status');

    function saveDeliverySchedule() {
        if (!dateInput) return;
        const payload = {
            jsonrpc: "2.0",
            method: "call",
            params: {
                delivery_date: dateInput.value,
                delivery_shift: shiftSelect ? shiftSelect.value : 'morning',
                delivery_notes: notesInput ? notesInput.value : ''
            }
        };
        fetch('/shop/b2b/set_delivery_schedule', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(payload)
        }).then(function(res) {
            return res.json();
        }).then(function(data) {
            if (data.result && data.result.success && statusEl) {
                statusEl.classList.remove('d-none');
                setTimeout(function() {
                    statusEl.classList.add('d-none');
                }, 2500);
            }
        }).catch(function(err) {
            console.error("Error saving B2B delivery schedule:", err);
        });
    }

    if (dateInput) dateInput.addEventListener('change', saveDeliverySchedule);
    if (shiftSelect) shiftSelect.addEventListener('change', saveDeliverySchedule);
    if (notesInput) notesInput.addEventListener('blur', saveDeliverySchedule);
});
